import math
import mmh3
import threading
import time
from typing import Optional, List

class WindowedHyperLogLog:
    """Memory-efficient windowed HyperLogLog cardinality estimator
    using fixed 8-bit registers within a 1KB bytearray, strict O(1) insertion,
    and time-decaying sliding windows."""

    def __init__(self, num_registers: int = 1024, window_ttl: float = 300.0) -> None:
        if num_registers & (num_registers - 1) != 0 or num_registers < 16:
            raise ValueError("num_registers must be a power of 2 and at least 16")
        self.num_registers = num_registers
        self.p = int(math.log2(num_registers))
        self.window_ttl = window_ttl

        self.registers = bytearray(num_registers)
        self.timestamps = [0.0] * num_registers
        self._lock = threading.Lock()

        # Alpha constant for HyperLogLog bias correction
        if num_registers == 16:
            self.alpha = 0.673
        elif num_registers == 32:
            self.alpha = 0.697
        elif num_registers == 64:
            self.alpha = 0.709
        else:
            self.alpha = 0.7213 / (1.0 + 1.079 / num_registers)

    def _hash(self, item: str) -> int:
        return mmh3.hash64(item, seed=42)[0] & 0xFFFFFFFFFFFFFFFF

    def _rho(self, w: int, max_bits: int = 64) -> int:
        if w == 0:
            return max_bits - self.p + 1
        return min(max_bits - self.p + 1, __import__('itertools').takewhile(lambda i: not (w & (1 << (max_bits - 1 - i))), range(max_bits - self.p)) 
                   and len(list(__import__('itertools').takewhile(lambda i: not (w & (1 << (max_bits - 1 - i))), range(max_bits - self.p)))) + 1 or 1)

    def add(self, item: str, current_time: Optional[float] = None) -> None:
        if not isinstance(item, str):
            raise TypeError("item must be a string")
        t = current_time if current_time is not None else time.time()
        h = self._hash(item)
        idx = h >> (64 - self.p)
        remaining_bits = h & ((1 << (64 - self.p)) - 1)

        # Compute rank rho
        leading_zeros = 1
        mask = 1 << (63 - self.p)
        while mask > 0 and (remaining_bits & mask) == 0:
            leading_zeros += 1
            mask >>= 1

        rank = min(255, leading_zeros)

        with self._lock:
            self._decay_unlocked(t)
            if rank > self.registers[idx]:
                self.registers[idx] = rank
                self.timestamps[idx] = t

    def _decay_unlocked(self, current_time: float) -> None:
        cutoff = current_time - self.window_ttl
        for i in range(self.num_registers):
            if self.timestamps[i] < cutoff:
                self.registers[i] = 0
                self.timestamps[i] = 0.0

    def decay(self, current_time: Optional[float] = None) -> None:
        t = current_time if current_time is not None else time.time()
        with self._lock:
            self._decay_unlocked(t)

    def estimate(self, current_time: Optional[float] = None) -> float:
        t = current_time if current_time is not None else time.time()
        with self._lock:
            self._decay_unlocked(t)

            sum_val = 0.0
            zero_count = 0
            for val in self.registers:
                if val == 0:
                    zero_count += 1
                sum_val += 2.0 ** (-val)

            if sum_val == 0.0:
                return 0.0

            raw_estimate = self.alpha * (self.num_registers ** 2) / sum_val

            # Small range correction (LinearCounting)
            if raw_estimate <= 2.5 * self.num_registers and zero_count > 0:
                return self.num_registers * math.log(self.num_registers / zero_count)

            return raw_estimate

    def merge(self, other: 'WindowedHyperLogLog', current_time: Optional[float] = None) -> None:
        if not isinstance(other, WindowedHyperLogLog):
            raise TypeError("Can only merge with another WindowedHyperLogLog instance")
        if self.num_registers != other.num_registers:
            raise ValueError("Cannot merge HLL estimators with differing register sizes")

        t = current_time if current_time is not None else time.time()
        with self._lock, other._lock:
            other._decay_unlocked(t)
            self._decay_unlocked(t)
            for i in range(self.num_registers):
                if other.registers[i] > self.registers[i]:
                    self.registers[i] = other.registers[i]
                    self.timestamps[i] = other.timestamps[i]
